// Stage How far an agent is trusted to act alone. State beside the specification rather than in it: a published version is immutable and promotion is not a new version.
type Stage string

// Step defines model for Step.
type Step struct {
	At time.Time `json:"at"`

	// Cost Cache tokens are reported separately from input tokens: a cache read
	// costs a fraction of the price, and without the split an expensive agent
	// cannot be diagnosed.
	Cost *Cost `json:"cost,omitempty"`

	// Hash Hex-encoded SHA-256 sealing this step to the previous one.
	Hash   string    `json:"hash"`
	Kind   StepKind  `json:"kind"`
	Labels *[]string `json:"labels,omitempty"`

	// Payload Kind-specific detail. Bulky content is not inlined: payloads carry
	// a reference into object storage plus a digest, because arguments
	// and results routinely contain personal data.
	Payload    *map[string]interface{} `json:"payload,omitempty"`
	PolicyHash *string                 `json:"policyHash,omitempty"`
	Seq        int64                   `json:"seq"`
}

// StepContent defines model for StepContent.
