func (sh *strictHandler) VerifyRun(w http.ResponseWriter, r *http.Request, runId RunId) {
	var request VerifyRunRequestObject

	request.RunId = runId

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.VerifyRun(ctx, request.(VerifyRunRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "VerifyRun")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(VerifyRunResponseObject); ok {
		if err := validResponse.VisitVerifyRunResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

